    nodeState.clear();

    traversal = newTraversal;

    mod  = {};
    loop = {};

    selectionRandom = (static_cast<unsigned int>(root) * 2654435761u
                       ^ static_cast<unsigned int>(newTraversal.key.typeId) * 40503u
                       ^ static_cast<unsigned int>(newTraversal.key.instance) * 2246822519u
                       ^ 2463534242u) | 1u;

    rootId              = root;
