void TraversalLogic::begin(const NodeMap& nodes, int startNodeId, int graphLoopLimit)
{
    primary.target = startNodeId;

    state = TraversalState::Active;

    loop.active = true;
    loop.count  = 0;
    loop.limit  = graphLoopLimit;

